#include <string.h>

static int usable(fmi2Status status) {
    return status == fmi2OK || status == fmi2Warning;
}

int inspect_me(fmi2String instanceName, fmi2String guid,
               fmi2String resourceLocation,
               const fmi2CallbackFunctions *callbacks, fmi2Real time,
               fmi2Real states[2], fmi2Real derivatives[2]) {
    fmi2Component component = fmi2Instantiate(instanceName, fmi2ModelExchange,
                                               guid, resourceLocation, callbacks,
                                               fmi2False, fmi2False);
    fmi2EventInfo eventInfo;
    int initializationExited = 0;
    int result = 0;
    if (component == NULL) return 0;

    if (!usable(fmi2SetupExperiment(component, fmi2False, 0.0,
                                    time, fmi2False, 0.0))) goto cleanup;
    if (!usable(fmi2EnterInitializationMode(component))) goto cleanup;
    if (!usable(fmi2ExitInitializationMode(component))) goto cleanup;
    initializationExited = 1;

    do {
        memset(&eventInfo, 0, sizeof(eventInfo));
        if (!usable(fmi2NewDiscreteStates(component, &eventInfo))) goto cleanup;
    } while (eventInfo.newDiscreteStatesNeeded);
    if (eventInfo.terminateSimulation) goto cleanup;

    if (!usable(fmi2EnterContinuousTimeMode(component))) goto cleanup;
    if (!usable(fmi2SetTime(component, time))) goto cleanup;
    if (!usable(fmi2GetContinuousStates(component, states, 2))) goto cleanup;
    if (!usable(fmi2GetDerivatives(component, derivatives, 2))) goto cleanup;
    result = 1;

cleanup:
    if (initializationExited) (void)fmi2Terminate(component);
    fmi2FreeInstance(component);
    return result;
}
